Replaced the linear scan with a lazily built direct lookup table indexed by message number, so each lookup becomes O(1) instead of O(MESGS). The table preserves the first-match behavior for duplicate numbers and works regardless of message ordering.

```cpp
const Profile::MESG* Profile::GetMesg(const FIT_UINT16 num)
{
    static FIT_UINT16 lookup[65536];
    static bool initialized = false;

    if (!initialized)
    {
        for (int i = 0; i < 65536; ++i)
            lookup[i] = 0xFFFF;

        for (int i = 0; i < MESGS; ++i)
        {
            const FIT_UINT16 n = mesgs[i].num;
            if (lookup[n] == 0xFFFF)
                lookup[n] = static_cast<FIT_UINT16>(i);
        }

        initialized = true;
    }

    const FIT_UINT16 idx = lookup[num];
    if (idx == 0xFFFF)
        return NULL;

    return &mesgs[idx];
}
```

